<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\{TermWorkflowService,AcademicService,EnrollmentService,AccessService,WaitingListService};
class ReferenceWorkspaceController extends Controller {
 public function promoteSections(Request $request){$data=$request->validate(['period_id'=>'required|integer|exists:periods,id','section_ids'=>'required|array|min:1|max:1000','section_ids.*'=>'integer|distinct|exists:sections,id','confirm'=>'required|accepted']);$sections=DB::table('sections')->whereIn('id',$data['section_ids'])->where('period_id',$data['period_id'])->pluck('id');if($sections->count()!==count($data['section_ids']))AcademicService::fail('All selected sections must belong to the selected semester.');$ids=DB::table('student_sections as m')->join('students as s','s.id','=','m.student_id')->whereIn('m.section_id',$sections)->where(['m.period_id'=>$data['period_id'],'s.active'=>true])->where('s.year_level','<',4)->pluck('s.id')->all();if(!$ids)return back()->with('status','No students below year four in the sections shown.');$request->merge(['action'=>'promote','student_ids'=>$ids]);return $this->studentAction($request,app(TermWorkflowService::class));}
 public function academicYears(Request $request){$request->validate(['academic_year'=>'nullable|regex:/^\d{4}-\d{4}$/','search'=>'nullable|string|max:100']);$years=DB::table('periods')->distinct()->orderByDesc('academic_year')->pluck('academic_year');$year=$request->input('academic_year',app(TermWorkflowService::class)->current()?->academic_year??$years->first());$students=DB::table('student_sections as m')->join('periods as t','t.id','=','m.period_id')->join('students as s','s.id','=','m.student_id')->join('users as u','u.id','=','s.user_id')->join('sections as sec','sec.id','=','m.section_id')->join('programs as p','p.id','=','sec.program_id')->where('t.academic_year',$year??'')->when($request->filled('search'),function($q)use($request){$term='%'.$request->input('search').'%';$q->where(fn($q)=>$q->where('u.name','like',$term)->orWhere('s.admission_id','like',$term)->orWhere('p.code','like',$term)->orWhere('sec.name','like',$term));})->select('s.id','s.admission_id','s.classification','u.name','p.code as program','sec.name as section','sec.year_level','t.semester','t.name as period')->orderByDesc('t.semester')->orderBy('p.code')->orderBy('u.name')->get()->unique('id')->values();$summary=$students->groupBy('program')->map(fn($rows)=>['total'=>$rows->count(),'sections'=>$rows->pluck('section')->unique()->sort()->implode(', '),'years'=>$rows->pluck('year_level')->unique()->sort()->implode(', ')]);return view('academic-years',compact('years','year','students','summary'));}
 public function sendSections(Request $request){$data=$request->validate(['period_id'=>'required|integer|exists:periods,id','section_ids'=>'required|array|min:1|max:1000','section_ids.*'=>'integer|distinct|exists:sections,id']);$sections=DB::table('sections')->whereIn('id',$data['section_ids'])->where(['period_id'=>$data['period_id'],'active'=>true])->pluck('id');if($sections->count()!==count($data['section_ids']))AcademicService::fail('All selected sections must be active in the selected semester.');$ids=DB::table('student_sections as m')->join('students as s','s.id','=','m.student_id')->leftJoin('enrollments as e',fn($j)=>$j->on('e.student_id','=','s.id')->where('e.period_id',$data['period_id']))->whereIn('m.section_id',$sections)->where(['m.period_id'=>$data['period_id'],'s.active'=>true,'s.classification'=>'regular'])->where(fn($q)=>$q->whereNull('e.id')->orWhereIn('e.status',['draft','revision_requested']))->orderBy('s.admission_id')->pluck('s.id')->all();if(!$ids) return back()->with('status','No waiting regular students in the sections shown.');$request->merge(['action'=>'send','student_ids'=>$ids]);return $this->studentAction($request,app(TermWorkflowService::class));}
 public function specialEnrollment(Request $request){$request->validate(['period_id'=>'nullable|integer|exists:periods,id','year_level'=>'nullable|integer|min:1|max:4','program_id'=>'nullable|integer|exists:programs,id']);$rows=DB::table('enrollments as e')->join('students as s','s.id','=','e.student_id')->join('users as u','u.id','=','s.user_id')->join('curriculums as c','c.id','=','s.curriculum_id')->join('programs as p','p.id','=','c.program_id')->join('periods as t','t.id','=','e.period_id')->where('s.classification','!=','regular')->when($request->filled('period_id'),fn($q)=>$q->where('e.period_id',$request->integer('period_id')))->when($request->filled('year_level'),fn($q)=>$q->where('s.year_level',$request->integer('year_level')))->when($request->filled('program_id'),fn($q)=>$q->where('p.id',$request->integer('program_id')))->select('e.*','u.name','s.classification','s.year_level','p.code as program','t.name as period')->orderByDesc('e.id')->paginate(20)->withQueryString();$assignments=DB::table('proposal_items as i')->join('enrollments as e',fn($j)=>$j->on('e.id','=','i.enrollment_id')->on('e.version','=','i.version'))->join('offerings as o','o.id','=','i.offering_id')->join('subjects as s','s.id','=','o.subject_id')->whereIn('e.id',$rows->pluck('id'))->select('e.id','s.code','s.units')->get()->groupBy('id');$periods=DB::table('periods')->orderByDesc('id')->get();$programs=DB::table('programs')->where('active',true)->get();return view('special-enrollment',compact('rows','periods','programs','assignments'));}
 public function sendSpecial(Request $request,EnrollmentService $service){$data=$request->validate(['enrollment_ids'=>'required|array|min:1|max:500','enrollment_ids.*'=>'required|integer|distinct|exists:enrollments,id']);$count=0;$errors=[];foreach($data['enrollment_ids'] as $id){try{DB::transaction(function()use($id,$service){$e=DB::table('enrollments')->find($id);if($e->status!=='special_ready')AcademicService::fail('Only a Department Head-forwarded draft can be sent.');$service->propose($e->student_id,$e->period_id,$service->items($e)->pluck('offering_id')->all());});$count++;}catch(\Illuminate\Validation\ValidationException $e){$errors[]='Enrollment #'.$id.': '.$e->getMessage();}}return back()->with('status',$count.' proposal(s) sent for student acceptance.')->with('workflow_errors',$errors);}
 public function calendar(TermWorkflowService $workflow){$periods=DB::table('periods')->orderByDesc('academic_year')->orderBy('semester')->get();$current=$workflow->current();$pipelinePeriod=$current;$locks=DB::table('schedule_locks')->get()->groupBy('period_id');$pipeline=app(\App\Services\EnrollmentPipelineService::class)->counts($current?->id);return view('term-calendar',compact('periods','current','locks','pipeline','pipelinePeriod'));}
 public function createTerm(Request $request){$data=$request->validate(['academic_year'=>'required|regex:/^\d{4}-\d{4}$/','semester'=>'required|in:1,2,3']);[$first,$last]=array_map('intval',explode('-',$data['academic_year']));if($last!==$first+1)AcademicService::fail('Use consecutive academic years.');if(DB::table('periods')->where($data)->exists())AcademicService::fail('That semester already exists.');$id=DB::table('periods')->insertGetId($data+['name'=>$data['academic_year'].' Semester '.$data['semester'],'active'=>true,'created_at'=>now(),'updated_at'=>now()]);app(AcademicService::class)->audit('semester_created','periods',$id);return back()->with('status','Semester created. Set its dates, then open it.');}
 public function term(Request $request,int $id,TermWorkflowService $workflow){$data=$request->validate(['action'=>'required|in:dates,activate,close,lock','start_date'=>'required_if:action,dates|nullable|date_format:Y-m-d','end_date'=>'required_if:action,dates|nullable|date_format:Y-m-d|after:start_date','year_level'=>'required_if:action,lock|nullable|integer|min:1|max:4','confirm'=>in_array($request->input('action'),['close','lock'])?'required|accepted':'nullable|boolean']);match($data['action']){'dates'=>$workflow->dates($id,array_intersect_key($data,array_flip(['start_date','end_date']))),'activate'=>$workflow->activate($id),'close'=>$workflow->close($id),'lock'=>$workflow->lock($id,(int)$data['year_level'])};return back()->with('status','Semester updated. Historical schedules and CORs are preserved.');}
 private function directoryQuery(Request $request,int $periodId){
  $q=DB::table('students as s')->join('users as u','u.id','=','s.user_id')->join('curriculums as c','c.id','=','s.curriculum_id')->join('programs as p','p.id','=','c.program_id')->leftJoin('colleges as col','col.id','=','p.college_id')->leftJoin('student_sections as b',fn($j)=>$j->on('b.student_id','=','s.id')->where('b.period_id',$periodId))->leftJoin('sections as sec','sec.id','=','b.section_id')->leftJoin('enrollments as e',fn($j)=>$j->on('e.student_id','=','s.id')->where('e.period_id',$periodId))->select('s.*','u.name','u.email','p.code as program','p.id as program_id','col.name as college','sec.name as section','b.section_id','e.id as enrollment_id','e.status')->selectRaw('COALESCE(sec.year_level,s.year_level) as year_level');
  if($request->user()->role==='department_head')$q->whereIn('s.id',app(AccessService::class)->studentIds())->where('s.classification','!=','regular');
  if($request->filled('stage')){$ids=app(\App\Services\EnrollmentPipelineService::class)->rows($periodId)->filter(fn($row)=>$request->input('stage')==='accepted'?in_array($row->stage,['accepted','finalized']):$row->stage===$request->input('stage'))->pluck('id');$q->whereIn('s.id',$ids);}
  foreach(['college_id'=>'p.college_id','program_id'=>'p.id','year_level'=>DB::raw('COALESCE(sec.year_level,s.year_level)'),'section_id'=>'b.section_id','admission_year'=>'s.admission_year','classification'=>'s.classification'] as $field=>$column)if($request->filled($field))$q->where($column,$request->input($field));
  if($request->boolean('unassigned'))$q->whereNull('b.id');if($request->filled('search')){$term='%'.$request->input('search').'%';$q->where(fn($q)=>$q->where('u.name','like',$term)->orWhere('s.admission_id','like',$term)->orWhere('s.student_number','like',$term));}return $q;
 }
 public function students(Request $request,TermWorkflowService $workflow){
  $request->validate(['search'=>'nullable|string|max:100','period_id'=>'nullable|integer|exists:periods,id','college_id'=>'nullable|integer|exists:colleges,id','program_id'=>'nullable|integer|exists:programs,id','year_level'=>'nullable|integer|min:1|max:4','section_id'=>'nullable|integer|exists:sections,id','admission_year'=>'nullable|integer|min:1900|max:2200','classification'=>'nullable|in:regular,irregular,transferee,returning']);
  $current=$workflow->current();$periodId=$request->integer('period_id')?:($current?->id??0);$query=$this->directoryQuery($request,$periodId);$summary=(clone $query)->get()->groupBy('program')->map(fn($rows)=>['total'=>$rows->count(),'years'=>$rows->groupBy('year_level')->map->count()]);$students=$query->orderBy('s.admission_id')->orderBy('u.name')->paginate(20)->withQueryString();
  $colleges=DB::table('colleges')->where('active',true)->orderBy('name')->get();$programs=DB::table('programs')->where('active',true)->orderBy('code')->get();$periods=DB::table('periods')->orderByDesc('academic_year')->orderBy('semester')->get();$sections=DB::table('sections')->where(['period_id'=>$periodId,'active'=>true])->orderBy('name')->get();$cohorts=DB::table('students')->whereNotNull('admission_year')->distinct()->orderByDesc('admission_year')->pluck('admission_year');$evaluations=DB::table('special_cases as e')->join('students as s','s.id','=','e.student_id')->whereColumn('e.curriculum_id','s.curriculum_id')->whereIn('e.student_id',$students->pluck('id'))->where('e.period_id',$periodId)->select('e.*')->orderByDesc('e.id')->get()->unique('student_id')->keyBy('student_id');$subjectCodes=DB::table('subjects')->pluck('code','id');foreach($evaluations as $evaluation)$evaluation->requested_codes=collect(json_decode($evaluation->requested_subject_ids??'[]',true))->map(fn($id)=>$subjectCodes[$id]??'')->filter()->implode(', ');return view('student-directory',compact('students','summary','current','periodId','colleges','programs','periods','sections','cohorts','evaluations'));
 }
 public function studentAction(Request $request,TermWorkflowService $workflow){
  $data=$request->validate(['action'=>'required|in:assign,auto_assign,send,promote','period_id'=>'required|integer|exists:periods,id','student_ids'=>'required|array|min:1|max:1000','student_ids.*'=>'integer|distinct|exists:students,id','section_id'=>'nullable|integer|exists:sections,id','confirm'=>$request->input('action')==='promote'?'required|accepted':'nullable|boolean']);$ok=0;$errors=[];
  foreach($data['student_ids'] as $id){try{
   if($data['action']==='assign'||$data['action']==='auto_assign')$workflow->assign($id,$data['period_id'],$data['action']==='assign'?($data['section_id']??null):null);
   elseif($data['action']==='promote')$workflow->promote($id,$data['period_id']);
   else{$membership=DB::table('student_sections')->where(['student_id'=>$id,'period_id'=>$data['period_id']])->first();if(!$membership)AcademicService::fail('Assign a primary section first.');$student=DB::table('students')->find($id);if($student->classification!=='regular')AcademicService::fail('Use Special enrollment for Department Head-reviewed assignments.');if(!DB::table('schedule_locks')->where(['period_id'=>$data['period_id'],'year_level'=>$student->year_level])->exists())AcademicService::fail('Finalize this year-level schedule before sending section proposals.');$ids=DB::table('offerings')->where(['section_id'=>$membership->section_id,'active'=>true])->pluck('id')->all();app(EnrollmentService::class)->propose($id,$data['period_id'],$ids);}
   $ok++;
  }catch(\Illuminate\Validation\ValidationException $e){$errors[]='Student #'.$id.': '.$e->getMessage();}}
  return back()->with('status',$ok.' student(s) updated.')->with('workflow_errors',$errors);
 }
 public function sections(Request $request,TermWorkflowService $workflow){$periodId=$request->integer('period_id')?:($workflow->current()?->id??0);$sections=DB::table('sections as s')->join('programs as p','p.id','=','s.program_id')->leftJoin('colleges as c','c.id','=','p.college_id')->where('s.period_id',$periodId)->when($request->filled('college_id'),fn($q)=>$q->where('p.college_id',$request->integer('college_id')))->when($request->filled('year_level'),fn($q)=>$q->where('s.year_level',$request->integer('year_level')))->select('s.*','p.code as program','c.name as college')->orderBy('s.name')->get();$counts=DB::table('student_sections')->where('period_id',$periodId)->select('section_id')->selectRaw('count(*) as total')->groupBy('section_id')->pluck('total','section_id');$periods=DB::table('periods')->orderByDesc('id')->get();$colleges=DB::table('colleges')->orderBy('name')->get();$programs=DB::table('programs')->where('active',true)->orderBy('code')->get();return view('section-directory',compact('sections','counts','periods','periodId','colleges','programs'));}
 public function section(Request $request,?int $id=null){$data=$request->validate(['period_id'=>'required|integer|exists:periods,id','capacity'=>'required|integer|min:1|max:500','program_id'=>'required_without:section_id|nullable|integer|exists:programs,id','year_level'=>'required_without:section_id|nullable|integer|min:1|max:4']);DB::transaction(function()use($id,$data){app(TermWorkflowService::class)->mutable($data['period_id'],(int)$data['year_level']);if($id){$section=DB::table('sections')->find($id);abort_unless($section&&$section->period_id==(int)$data['period_id'],404);$members=DB::table('student_sections')->where('section_id',$id)->count();$largest=DB::table('offerings')->where(['section_id'=>$id,'active'=>true])->max('capacity')??0;if($data['capacity']<max($members,$largest))AcademicService::fail('Capacity cannot be below existing memberships or class capacity.');DB::table('sections')->where('id',$id)->update(['capacity'=>$data['capacity'],'updated_at'=>now()]);app(AcademicService::class)->audit('section_capacity_changed','sections',$id,['capacity'=>$data['capacity']]);}else{$program=DB::table('programs')->find($data['program_id']);if(!$program->active)AcademicService::fail('Choose an active program.');$i=0;do{$n=$i++;$suffix='';do{$suffix=chr(65+$n%26).$suffix;$n=intdiv($n,26)-1;}while($n>=0);$name=$program->code.' '.$data['year_level'].$suffix;}while(DB::table('sections')->where(['period_id'=>$data['period_id'],'name'=>$name])->exists());$id=DB::table('sections')->insertGetId(array_intersect_key($data,array_flip(['period_id','capacity','program_id','year_level']))+['name'=>$name,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);app(AcademicService::class)->audit('section_created','sections',$id);}});return back()->with('status','Section saved.');}
 public function colleges(){ $colleges=DB::table('colleges')->orderBy('name')->get();$programs=DB::table('programs')->orderBy('code')->get()->groupBy('college_id');return view('colleges',compact('colleges','programs'));}
 public function waiting(Request $request,TermWorkflowService $workflow){$student=DB::table('students')->where('user_id',$request->user()->id)->first();abort_unless($student,404);$current=$workflow->current();$subjects=DB::table('curriculum_subjects as c')->join('subjects as s','s.id','=','c.subject_id')->where(['c.curriculum_id'=>$student->curriculum_id,'c.active'=>true])->whereNotIn('s.id',DB::table('academic_records')->where(['student_id'=>$student->id,'active'=>true])->whereIn('status',['PASSED','CREDITED'])->select('subject_id'))->select('s.*','c.year_level','c.semester')->orderBy('c.year_level')->orderBy('c.semester')->get();$entries=DB::table('subject_waiting_list as w')->join('subjects as s','s.id','=','w.subject_id')->where('w.student_id',$student->id)->select('w.*','s.code','s.name')->orderByDesc('w.id')->get();return view('waiting-list',compact('student','current','subjects','entries'));}
 public function requestSubjects(Request $request,WaitingListService $workflow){$data=$request->validate(['period_id'=>'required|exists:periods,id','subject_ids'=>'required|array|min:1|max:50','subject_ids.*'=>'integer|distinct|exists:subjects,id','remarks'=>'required|string|max:5000']);$student=DB::table('students')->where('user_id',$request->user()->id)->first();abort_unless($student&&$student->active,403);if($student->classification==='regular')AcademicService::fail('Back-subject requests are for special classifications. Contact the Registrar to review your classification.');$workflow->request($student,(int)$data['period_id'],$data['subject_ids'],$data['remarks']);return back()->with('status','Request recorded. Eligible classes go to the Department Head; other subjects remain on your waiting list.');}
}
